+    raise exception 'refusing to run B1 query contract rehearsal against archive project %', archive_ref;
+  end if;
+end
+$guard$;
+
+drop function if exists private.kg_v1_b1_get_runtime_contract(text);
+drop view if exists private.kg_v1_b1_rag_read_model_contract;
+drop view if exists private.kg_v1_b1_review_routing_contract;
