+
+create or replace view private.kg_v1_b1_question_availability_contract
+with (security_invoker = true) as
+select
+  projection.question_key,
+  coalesce(question.properties ->> 'question_ref', projection.payload ->> 'question_ref', projection.payload ->> 'question_row_id') as question_ref,
+  coalesce(question.properties ->> 'question_row_id', projection.payload ->> 'question_row_id', projection.question_key) as question_row_id,
+  projection.payload ->> 'question_availability' as question_availability,
+  projection.payload ->> 'source_question_availability' as source_question_availability,
+  coalesce((projection.payload ->> 'question_availability_independent_of_method_evidence')::boolean, true) as question_availability_independent_of_method_evidence,
+  projection.payload ->> 'method_confidence_bucket' as method_confidence_bucket,
+  (projection.payload ->> 'method_confidence_score')::numeric as method_confidence_score,
+  coalesce((projection.payload ->> 'method_confidence_blocks_availability')::boolean, false) as method_confidence_blocks_availability,
+  coalesce((projection.payload ->> 'low_or_provisional_confidence')::boolean, false) as low_or_provisional_confidence,
+  question.properties as question_properties,
+  projection.payload as source_payload,
+  'private.kg_v1_b0_query_projection_rows'::text as source_relation,
+  'local_sql_b0_import'::text as source_query_basis
+from private.kg_v1_b0_query_projection_rows projection
+left join private.kg_v1_b0_nodes question
+  on question.node_family = 'Question'
+  and question.question_key = projection.question_key
+where projection.surface_id = 'question_runtime_availability';
+
+create or replace view private.kg_v1_b1_visual_dependency_contract
+with (security_invoker = true) as
+select
+  projection.question_key,
+  coalesce(question.properties ->> 'question_ref', projection.payload ->> 'question_ref', projection.question_key) as question_ref,
+  coalesce((question.properties ->> 'requires_image_context')::boolean, (projection.payload ->> 'visual_dependency_present')::boolean, false) as requires_image_context,
+  (projection.payload ->> 'source_visual_receipt_accepted')::boolean as source_visual_receipt_accepted,
+  coalesce((projection.payload ->> 'visual_qa_accepted')::boolean, false) as visual_qa_accepted,
+  coalesce((projection.payload ->> 'visual_dependency_present')::boolean, false) as visual_dependency_present,
+  coalesce((projection.payload ->> 'visual_dependency_ready')::boolean, false) as visual_dependency_ready,
+  projection.payload ->> 'visual_display_blocker_reason' as visual_display_blocker_reason,
+  projection.payload ->> 'student_display_blocker_reason' as student_display_blocker_reason,
+  case
+    when coalesce((projection.payload ->> 'visual_dependency_present')::boolean, false) = false then 'not_visual_required'
+    when coalesce((projection.payload ->> 'visual_dependency_ready')::boolean, false) then 'visual_dependency_ready'
+    else 'visual_dependency_blocked'
+  end as visual_dependency_state,
+  projection.payload as source_payload,
+  'local_sql_b0_import'::text as source_query_basis
+from private.kg_v1_b0_query_projection_rows projection
+left join private.kg_v1_b0_nodes question
+  on question.node_family = 'Question'
+  and question.question_key = projection.question_key
