+  coalesce((projection.payload ->> 'student_display_eligible_final')::boolean, false) as student_display_eligible_final,
+  coalesce((projection.payload ->> 'rights_display_allowed')::boolean, false) as rights_display_allowed,
+  (projection.payload ->> 'source_visual_receipt_accepted')::boolean as source_visual_receipt_accepted,
+  coalesce((projection.payload ->> 'visual_qa_accepted')::boolean, false) as visual_qa_accepted,
+  coalesce((projection.payload ->> 'raw_vlm_candidate')::boolean, false) as raw_vlm_candidate,
+  coalesce((projection.payload ->> 'unreviewed_visual_asset')::boolean, false) as unreviewed_visual_asset,
+  projection.payload ->> 'student_display_blocker_reason' as student_display_blocker_reason,
+  projection.payload ->> 'visual_display_blocker_reason' as visual_display_blocker_reason,
