+create or replace function private.kg_v1_b1_get_runtime_contract(target_question_key text default null)
+returns table(surface_id text, question_key text, contract_payload jsonb)
+language sql
+stable
+security invoker
+set search_path = private, pg_temp
+as $function$
+  select
+    'question_availability'::text as surface_id,
+    question_key,
+    to_jsonb(row) - 'source_payload' as contract_payload
+  from private.kg_v1_b1_question_availability_contract row
+  where target_question_key is null or question_key = target_question_key
+  union all
