+} = {}) {
+  const commandResults = [];
+  const blockersList = [];
+  const helpResult = runCommand('supabase', ['--help'], { timeoutMs: 30000 });
+  commandResults.push(commandResult('supabase_cli_help_discovery', 'supabase --help', helpResult));
+  const versionResult = runCommand('supabase', ['--version'], { timeoutMs: 30000 });
+  commandResults.push(commandResult('supabase_cli_version_discovery', 'supabase --version', versionResult, {
+    observed_version: versionResult.status === 0 ? versionResult.stdout.trim() : null,
