+where projection.surface_id = 'diagnostic_posture_and_evidence_reason';
+
+create or replace view private.kg_v1_b1_review_routing_contract
+with (security_invoker = true) as
+select
+  projection.question_key,
+  coalesce(question.properties ->> 'question_ref', projection.payload ->> 'question_ref', projection.question_key) as question_ref,
+  projection.payload ->> 'review_routing_posture' as review_routing_posture,
+  projection.payload ->> 'review_queue' as review_queue,
+  projection.payload ->> 'rights_display_status' as rights_display_status,
+  projection.payload -> 'source_refs' as source_refs,
+  case
+    when projection.payload ->> 'review_queue' is null then 'review_route_missing'
+    else 'review_route_ready'
+  end as review_route_state,
+  projection.payload as source_payload,
+  'local_sql_b0_import'::text as source_query_basis
+from private.kg_v1_b0_query_projection_rows projection
+left join private.kg_v1_b0_nodes question
+  on question.node_family = 'Question'
+  and question.question_key = projection.question_key
+where projection.surface_id = 'review_queue_routing';
+
+create or replace view private.kg_v1_b1_rag_read_model_contract
+with (security_invoker = true) as
+select
+  projection.question_key,
+  coalesce(question.properties ->> 'question_ref', availability.payload ->> 'question_ref', projection.question_key) as question_ref,
+  coalesce((projection.payload ->> 'rag_projection_eligible')::boolean, false) as rag_projection_eligible,
+  coalesce((projection.payload ->> 'student_display_eligible_final')::boolean, false) as student_display_eligible_final,
+  projection.payload ->> 'method_confidence_bucket' as method_confidence_bucket,
+  availability.payload ->> 'question_availability' as question_availability,
+  case
+    when coalesce((projection.payload ->> 'rag_projection_eligible')::boolean, false) then 'rag_read_model_projection_eligible'
+    when availability.payload ->> 'question_availability' = 'blocked_invalid_student_question_missing_required_visual' then 'rag_read_model_blocked_visual_dependency'
+    else 'rag_read_model_not_eligible'
+  end as rag_contract_state,
+  projection.payload as source_payload,
+  'local_sql_b0_import'::text as source_query_basis
+from private.kg_v1_b0_query_projection_rows projection
+left join private.kg_v1_b0_query_projection_rows availability
+  on availability.surface_id = 'question_runtime_availability'
+  and availability.question_key = projection.question_key
+left join private.kg_v1_b0_nodes question
+  on question.node_family = 'Question'
+  and question.question_key = projection.question_key
+where projection.surface_id = 'rag_read_model_projection_eligibility';
+
+create or replace function private.kg_v1_b1_get_runtime_contract(target_question_key text default null)
+returns table(surface_id text, question_key text, contract_payload jsonb)
+language sql
+stable
+security invoker
+set search_path = private, pg_temp
+as $function$
+  select
+    'question_availability'::text as surface_id,
+    question_key,
+    to_jsonb(row) - 'source_payload' as contract_payload
+  from private.kg_v1_b1_question_availability_contract row
+  where target_question_key is null or question_key = target_question_key
+  union all
+  select 'visual_dependency'::text, question_key, to_jsonb(row) - 'source_payload'
+  from private.kg_v1_b1_visual_dependency_contract row
+  where target_question_key is null or question_key = target_question_key
+  union all
+  select 'student_display'::text, question_key, to_jsonb(row) - 'source_payload'
+  from private.kg_v1_b1_student_display_contract row
+  where target_question_key is null or question_key = target_question_key
+  union all
+  select 'diagnostic_posture'::text, question_key, to_jsonb(row) - 'source_payload'
+  from private.kg_v1_b1_diagnostic_posture_contract row
+  where target_question_key is null or question_key = target_question_key
+  union all
+  select 'review_routing'::text, question_key, to_jsonb(row) - 'source_payload'
+  from private.kg_v1_b1_review_routing_contract row
+  where target_question_key is null or question_key = target_question_key
+  union all
+  select 'rag_read_model'::text, question_key, to_jsonb(row) - 'source_payload'
+  from private.kg_v1_b1_rag_read_model_contract row
+  where target_question_key is null or question_key = target_question_key
+$function$;
+
+comment on view private.kg_v1_b1_question_availability_contract is
+  'B1 local/disposable query contract: question runtime availability, derived from imported B0 SQL rows.';
+comment on view private.kg_v1_b1_visual_dependency_contract is
