+revoke all on private.kg_v1_b1_question_availability_contract from anon, authenticated;
+revoke all on private.kg_v1_b1_visual_dependency_contract from anon, authenticated;
+revoke all on private.kg_v1_b1_student_display_contract from anon, authenticated;
+revoke all on private.kg_v1_b1_diagnostic_posture_contract from anon, authenticated;
+revoke all on private.kg_v1_b1_review_routing_contract from anon, authenticated;
+revoke all on private.kg_v1_b1_rag_read_model_contract from anon, authenticated;
+revoke all on function private.kg_v1_b1_get_runtime_contract(text) from public, anon, authenticated;
+
+grant usage on schema private to service_role;
+grant select on private.kg_v1_b1_question_availability_contract to service_role;
+grant select on private.kg_v1_b1_visual_dependency_contract to service_role;
+grant select on private.kg_v1_b1_student_display_contract to service_role;
