+    ) as security_invoker_view_count,
+    (
+      select count(*)::integer
+      from pg_proc p
+      join pg_namespace n on n.oid = p.pronamespace
+      where n.nspname = 'private'
+        and p.proname = 'kg_v1_b1_get_runtime_contract'
+    ) as rpc_contract_count,
