+  ) as payload
+  from private.kg_v1_b1_question_availability_contract availability
+  join private.kg_v1_b1_visual_dependency_contract visual using (question_key)
+  join private.kg_v1_b1_student_display_contract display using (question_key)
+  join private.kg_v1_b1_review_routing_contract review using (question_key)
+  join private.kg_v1_b1_rag_read_model_contract rag using (question_key)
+  where availability.question_key = 'qrow_9709_m16_qp_12_q01'
+),
+blocked_probe as (
+  select jsonb_build_object(
+    'question_key', availability.question_key,
+    'question_ref', availability.question_ref,
+    'question_availability', availability.question_availability,
+    'visual_dependency_ready', visual.visual_dependency_ready,
+    'student_display_blocker_reason', display.student_display_blocker_reason,
+    'rag_projection_eligible', rag.rag_projection_eligible,
+    'evidence_reason', diagnostic.evidence_reason
+  ) as payload
+  from private.kg_v1_b1_question_availability_contract availability
+  join private.kg_v1_b1_visual_dependency_contract visual using (question_key)
+  join private.kg_v1_b1_student_display_contract display using (question_key)
+  join private.kg_v1_b1_diagnostic_posture_contract diagnostic using (question_key)
+  join private.kg_v1_b1_rag_read_model_contract rag using (question_key)
+  where availability.question_key = 'qrow_9709_m16_qp_12_q09'
+)
+select jsonb_build_object(
+  'count_source', 'local_sql_b1_contract_probes',
+  'question_availability_rows', contract_counts.question_availability_rows,
+  'visual_dependency_rows', contract_counts.visual_dependency_rows,
+  'student_display_eligibility_rows', contract_counts.student_display_eligibility_rows,
+  'diagnostic_posture_rows', contract_counts.diagnostic_posture_rows,
+  'review_routing_rows', contract_counts.review_routing_rows,
+  'rag_read_model_eligibility_rows', contract_counts.rag_read_model_eligibility_rows,
+  'contract_surface_count', catalog_counts.contract_surface_count,
+  'rpc_contract_count', catalog_counts.rpc_contract_count,
+  'question_nodes', contract_counts.question_nodes,
+  'visual_required_rows', contract_counts.visual_required_rows,
+  'visual_dependency_present_rows', contract_counts.visual_dependency_present_rows,
+  'visual_dependency_blocked_rows', contract_counts.visual_dependency_blocked_rows,
+  'availability_attemptable_rows', contract_counts.availability_attemptable_rows,
+  'availability_visual_placeholder_rows', contract_counts.availability_visual_placeholder_rows,
+  'availability_blocked_missing_visual_rows', contract_counts.availability_blocked_missing_visual_rows,
+  'student_display_eligible_rows', contract_counts.student_display_eligible_rows,
+  'rag_projection_eligible_rows', contract_counts.rag_projection_eligible_rows,
+  'diagnostic_visual_not_ready_rows', contract_counts.diagnostic_visual_not_ready_rows,
+  'review_queue_method_map_rows', contract_counts.review_queue_method_map_rows,
+  'anon_authenticated_private_grant_count', catalog_counts.anon_authenticated_private_grant_count,
+  'security_invoker_view_count', catalog_counts.security_invoker_view_count,
+  'security_invoker_function_count', catalog_counts.security_invoker_function_count,
+  'clean_probe', coalesce((select payload from clean_probe), '{}'::jsonb),
+  'blocked_probe', coalesce((select payload from blocked_probe), '{}'::jsonb)
+)::text as kg_b1_local_sql_query_probe
+from contract_counts, catalog_counts;`;
+}
