+export async function runLocalDisposableQueryRehearsal({
+  root = repoRootFromScript(),
+  paths = DEFAULT_PATHS,
+  databaseUrl = null,
+  generatedAt = new Date().toISOString(),
+  databaseName = null,
+} = {}) {
+  const commandResults = [];
+  const blockersList = [];
+  const helpResult = runCommand('supabase', ['--help'], { timeoutMs: 30000 });
+  commandResults.push(commandResult('supabase_cli_help_discovery', 'supabase --help', helpResult));
+  const versionResult = runCommand('supabase', ['--version'], { timeoutMs: 30000 });
+  commandResults.push(commandResult('supabase_cli_version_discovery', 'supabase --version', versionResult, {
+    observed_version: versionResult.status === 0 ? versionResult.stdout.trim() : null,
+  }));
+  if (helpResult.status !== 0) {
+    blockersList.push(makeBlocker('supabase_cli_help_unavailable', 'supabase --help failed before local command discovery.'));
+  }
+
+  const statusResult = runCommand('supabase', ['status', '-o', 'json'], { timeoutMs: 30000 });
+  commandResults.push(commandResult('local_status_probe', 'supabase status -o json', statusResult));
+
+  let statusParse = {
+    dbUrl: null,
+    status: {
+      db_url_present: false,
+      stopped_services: [],
+      raw_status_available: false,
+    },
+  };
+  if (statusResult.status === 0) {
+    try {
+      statusParse = parseSupabaseStatus(`${statusResult.stdout}\n${statusResult.stderr}`);
+    } catch (error) {
+      blockersList.push(makeBlocker('local_supabase_status_parse_failed', error.message));
+    }
+  }
+
+  const adminUrl = databaseUrl ?? statusParse.dbUrl ?? null;
+  if (statusResult.status !== 0 && !databaseUrl) {
+    blockersList.push(makeBlocker('local_supabase_status_unavailable', 'supabase status did not return successfully.'));
+  }
+  if (!adminUrl) {
+    blockersList.push(makeBlocker('local_database_url_missing', 'No local Supabase database URL was available.'));
+  } else if (!localDatabaseUrl(adminUrl)) {
+    blockersList.push(makeBlocker('non_local_database_url_refused', 'The resolved database URL is not localhost or 127.0.0.1.'));
+  }
+
+  if (blockersList.length > 0) {
+    return {
+      status: 'blocked_local_env',
+      target_type: 'local_disposable_supabase_postgres_database',
+      supabase_status: statusParse.status,
+      command_results: commandResults,
+      blockers: blockersList,
+      remote_fallback_attempted: false,
+      remote_supabase_mutation_performed: false,
+    };
+  }
+
+  const runtimeSpine = JSON.parse(fs.readFileSync(path.join(root, paths.runtimeSpineIn), 'utf8'));
+  const querySurfaces = JSON.parse(fs.readFileSync(path.join(root, paths.querySurfacesIn), 'utf8'));
+  const runDatabaseName = databaseName ?? cleanDatabaseName(generatedAt);
+  const disposableUrl = databaseUrlForDatabase(adminUrl, runDatabaseName);
+  const targetProjectRef = 'local-cie-1290-kg-b1';
+  let created = false;
+  let dropped = false;
+
+  try {
+    const createResult = runCommand('createdb', createdbArgs(adminUrl, runDatabaseName), {
+      env: postgresAdminEnv(adminUrl),
+      timeoutMs: 30000,
+    });
+    commandResults.push(commandResult('create_disposable_database', 'createdb local-redacted-url', createResult));
+    if (createResult.status !== 0) {
+      blockersList.push(makeBlocker('createdb_failed', 'Unable to create the local disposable rehearsal database.'));
+      throw new Error('createdb_failed');
+    }
+    created = true;
+
+    for (const [step, relPath] of [
+      ['apply_kg_b0_schema_sql', paths.b0SchemaSql],
+      ['apply_kg_b0_projection_sql', paths.b0ProjectionSql],
+    ]) {
+      const applyResult = applyPsqlFile(disposableUrl, path.join(root, relPath), targetProjectRef);
+      commandResults.push(commandResult(step, 'psql local-redacted-url local-disposable SQL file', applyResult));
+      if (applyResult.status !== 0) {
+        blockersList.push(makeBlocker(`${step}_failed`, `Unable to apply ${relPath}.`));
+        throw new Error(`${step}_failed`);
+      }
+    }
+
+    const gitShaResult = runCommand('git', ['rev-parse', 'HEAD'], { timeoutMs: 30000 });
+    commandResults.push(commandResult('git_sha_probe', 'git rev-parse HEAD', gitShaResult));
+    const importReadback = await importKgData({
+      databaseUrl: disposableUrl,
+      runtimeSpine,
+      querySurfaces,
+      gitSha: gitShaResult.status === 0 ? gitShaResult.stdout.trim() : null,
+    });
+    commandResults.push({
+      step: 'import_kg_b0_nodes_edges_postures_query_surfaces',
+      command_class: 'node pg local-redacted-url import',
+      exit_code: 0,
+      imported_nodes: importReadback.imported_nodes,
+      imported_edges: importReadback.imported_edges,
+      imported_postures: importReadback.imported_postures,
+      imported_query_projection_rows: importReadback.imported_query_projection_rows,
+    });
+
+    const securityResult = applyPsqlFile(disposableUrl, path.join(root, paths.b0SecuritySql), targetProjectRef);
+    commandResults.push(commandResult('apply_kg_b0_security_sql', 'psql local-redacted-url local-disposable SQL file', securityResult));
+    if (securityResult.status !== 0) {
+      blockersList.push(makeBlocker('apply_kg_b0_security_sql_failed', `Unable to apply ${paths.b0SecuritySql}.`));
+      throw new Error('apply_kg_b0_security_sql_failed');
+    }
+
+    const tempContractPath = path.join(root, paths.contractSqlOut);
+    const contractResult = applyPsqlFile(disposableUrl, tempContractPath, targetProjectRef);
+    commandResults.push(commandResult('apply_kg_b1_contract_sql', 'psql local-redacted-url local-disposable SQL file', contractResult));
+    if (contractResult.status !== 0) {
+      blockersList.push(makeBlocker('apply_kg_b1_contract_sql_failed', `Unable to apply ${paths.contractSqlOut}.`));
+      throw new Error('apply_kg_b1_contract_sql_failed');
+    }
+
+    const probeResult = runCommand('psql', [disposableUrl, '-X', '-A', '-t', '-q', '-c', kgB1ProbeSql()], {
+      timeoutMs: 120000,
+    });
+    commandResults.push(commandResult('verify_kg_b1_query_probes', 'psql local-redacted-url query probes', probeResult));
+    if (probeResult.status !== 0) {
+      blockersList.push(makeBlocker('kg_b1_query_probe_failed', 'Unable to read back local SQL B1 query probes.'));
+      throw new Error('kg_b1_query_probe_failed');
+    }
+    const sqlQueryReadback = JSON.parse(probeResult.stdout.trim());
+
+    const dropResult = runCommand('dropdb', dropdbArgs(adminUrl, runDatabaseName), {
+      env: postgresAdminEnv(adminUrl),
+      timeoutMs: 30000,
+    });
+    commandResults.push(commandResult('drop_disposable_database', 'dropdb local-redacted-url', dropResult));
+    dropped = dropResult.status === 0;
+    if (!dropped) {
+      blockersList.push(makeBlocker('dropdb_failed', 'Unable to drop the local disposable rehearsal database.'));
+      throw new Error('dropdb_failed');
+    }
+
+    const existsResult = runCommand('psql', [adminUrl, '-X', '-A', '-t', '-q', '-c', databaseExistsSql(runDatabaseName)], {
+      timeoutMs: 30000,
+    });
+    commandResults.push(commandResult('verify_disposable_database_absent', 'psql local-redacted-url database absence', existsResult));
+    const remainingCount = parseRemainingDatabaseCount(existsResult);
+
+    return {
+      status: 'completed',
+      target_type: 'local_disposable_supabase_postgres_database',
+      database_name: runDatabaseName,
+      database_redacted_url: sanitizedDatabaseDescriptor(redactDatabaseUrl(disposableUrl)),
+      supabase_status: statusParse.status,
+      command_results: commandResults,
+      import_readback: importReadback,
+      sql_query_readback: sqlQueryReadback,
+      cleanup_readback: {
+        rollback_executed: true,
