+export async function runLocalDisposableQueryRehearsal({
+  root = repoRootFromScript(),
+  paths = DEFAULT_PATHS,
+  databaseUrl = null,
+  generatedAt = new Date().toISOString(),
+  databaseName = null,
+} = {}) {
+  const commandResults = [];
+  const blockersList = [];
+  const helpResult = runCommand('supabase', ['--help'], { timeoutMs: 30000 });
+  commandResults.push(commandResult('supabase_cli_help_discovery', 'supabase --help', helpResult));
+  const versionResult = runCommand('supabase', ['--version'], { timeoutMs: 30000 });
+  commandResults.push(commandResult('supabase_cli_version_discovery', 'supabase --version', versionResult, {
+    observed_version: versionResult.status === 0 ? versionResult.stdout.trim() : null,
+  }));
+  if (helpResult.status !== 0) {
+    blockersList.push(makeBlocker('supabase_cli_help_unavailable', 'supabase --help failed before local command discovery.'));
+  }
+
+  const statusResult = runCommand('supabase', ['status', '-o', 'json'], { timeoutMs: 30000 });
+  commandResults.push(commandResult('local_status_probe', 'supabase status -o json', statusResult));
+
+  let statusParse = {
+    dbUrl: null,
+    status: {
+      db_url_present: false,
+      stopped_services: [],
+      raw_status_available: false,
+    },
+  };
+  if (statusResult.status === 0) {
+    try {
+      statusParse = parseSupabaseStatus(`${statusResult.stdout}\n${statusResult.stderr}`);
+    } catch (error) {
+      blockersList.push(makeBlocker('local_supabase_status_parse_failed', error.message));
+    }
+  }
+
+  const adminUrl = databaseUrl ?? statusParse.dbUrl ?? null;
+  if (statusResult.status !== 0 && !databaseUrl) {
+    blockersList.push(makeBlocker('local_supabase_status_unavailable', 'supabase status did not return successfully.'));
+  }
+  if (!adminUrl) {
+    blockersList.push(makeBlocker('local_database_url_missing', 'No local Supabase database URL was available.'));
+  } else if (!localDatabaseUrl(adminUrl)) {
+    blockersList.push(makeBlocker('non_local_database_url_refused', 'The resolved database URL is not localhost or 127.0.0.1.'));
+  }
+
+  if (blockersList.length > 0) {
+    return {
+      status: 'blocked_local_env',
+      target_type: 'local_disposable_supabase_postgres_database',
+      supabase_status: statusParse.status,
+      command_results: commandResults,
+      blockers: blockersList,
+      remote_fallback_attempted: false,
+      remote_supabase_mutation_performed: false,
+    };
+  }
+
+  const runtimeSpine = JSON.parse(fs.readFileSync(path.join(root, paths.runtimeSpineIn), 'utf8'));
+  const querySurfaces = JSON.parse(fs.readFileSync(path.join(root, paths.querySurfacesIn), 'utf8'));
